CREATE TABLE IF NOT EXISTS on_call_shifts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES platform_users(id) ON DELETE CASCADE,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,note TEXT,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT REFERENCES platform_users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS on_call_shifts_active_idx ON on_call_shifts(enabled,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS alert_assignments(id TEXT PRIMARY KEY,alert_event_id TEXT NOT NULL UNIQUE REFERENCES alert_events(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES platform_users(id) ON DELETE CASCADE,shift_id TEXT REFERENCES on_call_shifts(id) ON DELETE SET NULL,assignment_type TEXT NOT NULL DEFAULT 'on_call' CHECK(assignment_type IN ('on_call','manual')),assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS alert_assignments_user_idx ON alert_assignments(user_id,assigned_at DESC);
